package com.bank.streamreuse;

import java.util.*;
import java.util.logging.*;

public class ReuseDemo {
    private static final Logger log = Logger.getLogger("StreamReuse");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Integer> data = List.of(1, 2, 3);
        StreamReuseService service = new StreamReuseService();

        service.demonstrateReuseError(log, data);   // throws on 2nd terminal
        service.correctReuse(log, data);            // re-stream the source
    }
}

// ─── Would be in service/StreamReuseService.java ───
class StreamReuseService {
    // BUG: operate on the SAME stream twice
    void demonstrateReuseError(Logger log, List<Integer> data) {
        java.util.stream.Stream<Integer> s = data.stream();
        long count = s.count();                      // terminal #1 — consumes s
        try {
            List<Integer> list = s.toList();         // terminal #2 — throws!
            log.info(() -> "list: " + list);
        } catch (IllegalStateException ex) {
            log.severe(() -> "reuse → " + ex.getMessage());
        }
    }

    // FIX: create a NEW stream from the source each time
    void correctReuse(Logger log, List<Integer> data) {
        long count = data.stream().count();          // fresh stream
        List<Integer> list = data.stream().toList(); // another fresh stream
        log.info(() -> "count=" + count + " list=" + list);
    }
}
